import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.ecommerceSettings().getEcommerceSettings();
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("ecommerce_settings");
Map<?, ?> continueShopping = (Map<?, ?>) settings.get("continue_shopping");
Map<?, ?> orderFilters = (Map<?, ?>) settings.get("order_filters");
System.out.println(continueShopping.get("continue_shopping_target"));
System.out.println(orderFilters.get("default_shipment_status"));
for (Object row : (List<?>) settings.get("order_flags")) {
    Map<?, ?> orderFlag = (Map<?, ?>) row;
    System.out.println(orderFlag.get("id") + " " + orderFlag.get("name"));
}

