import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.ecommerceSettings().patchEcommerceSettings(Map.of("ecommerce_settings", Map.of(
        "continue_shopping", Map.of("continue_shopping_target", "previous"),
        "order_filters", Map.of("default_payment_status", "unpaid"))));
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("ecommerce_settings");
System.out.println(((Map<?, ?>) settings.get("continue_shopping")).get("continue_shopping_target"));
System.out.println(((Map<?, ?>) settings.get("order_filters")).get("default_payment_status"));

